mkitem!{mktrait!{# [doc = " `DispatchFromDyn` is used in the implementation of dyn-compatibility[^1] checks (specifically"] # [doc = " allowing arbitrary self types), to guarantee that a method's receiver type can be dispatched on."] # [doc = ""] # [doc = " Note: `DispatchFromDyn` was briefly named `CoerceSized` (and had a slightly different"] # [doc = " interpretation)."] # [doc = ""] # [doc = " Imagine we have a trait object `t` with type `&dyn Tr`, where `Tr` is some trait with a method"] # [doc = " `m` defined as `fn m(&self);`. When calling `t.m()`, the receiver `t` is a wide pointer, but an"] # [doc = " implementation of `m` will expect a narrow pointer as `&self` (a reference to the concrete"] # [doc = " type). The compiler must generate an implicit conversion from the trait object/wide pointer to"] # [doc = " the concrete reference/narrow pointer. Implementing `DispatchFromDyn` indicates that that"] # [doc = " conversion is allowed and thus that the type implementing `DispatchFromDyn` is safe to use as"] # [doc = " the self type in an dyn-compatible method. (in the above example, the compiler will require"] # [doc = " `DispatchFromDyn` is implemented for `&'a U`)."] # [doc = ""] # [doc = " `DispatchFromDyn` does not specify the conversion from wide pointer to narrow pointer; the"] # [doc = " conversion is hard-wired into the compiler. For the conversion to work, the following"] # [doc = " properties must hold (i.e., it is only safe to implement `DispatchFromDyn` for types which have"] # [doc = " these properties, these are also checked by the compiler):"] # [doc = ""] # [doc = " * EITHER `Self` and `T` are either both references or both raw pointers; in either case, with"] # [doc = "   the same mutability."] # [doc = " * OR, all of the following hold"] # [doc = "   - `Self` and `T` must have the same type constructor, and only vary in a single type parameter"] # [doc = "     formal (the *coerced type*, e.g., `impl DispatchFromDyn<Rc<T>> for Rc<U>` is ok and the"] # [doc = "     single type parameter (instantiated with `T` or `U`) is the coerced type,"] # [doc = "     `impl DispatchFromDyn<Arc<T>> for Rc<U>` is not ok)."] # [doc = "   - The definition for `Self` must be a struct."] # [doc = "   - The definition for `Self` must not be `#[repr(packed)]` or `#[repr(C)]`."] # [doc = "   - Other than one-aligned, zero-sized fields, the definition for `Self` must have exactly one"] # [doc = "     field and that field's type must be the coerced type. Furthermore, `Self`'s field type must"] # [doc = "     implement `DispatchFromDyn<F>` where `F` is the type of `T`'s field type."] # [doc = ""] # [doc = " An example implementation of the trait:"] # [doc = ""] # [doc = " ```"] # [doc = " # #![feature(dispatch_from_dyn, unsize)]"] # [doc = " # use std::{ops::DispatchFromDyn, marker::Unsize};"] # [doc = " # struct Rc<T: ?Sized>(std::rc::Rc<T>);"] # [doc = " impl<T: ?Sized, U: ?Sized> DispatchFromDyn<Rc<U>> for Rc<T>"] # [doc = " where"] # [doc = "     T: Unsize<U>,"] # [doc = " {}"] # [doc = " ```"] # [doc = ""] # [doc = " [^1]: Formerly known as *object safety*."] # [unstable (feature = "dispatch_from_dyn" , issue = "none")] # [lang = "dispatch_from_dyn"] pub trait DispatchFromDyn < T > { }}}
mkitem!{mkimpl!{# [unstable (feature = "dispatch_from_dyn" , issue = "none")] impl < 'a , T : PointeeSized + Unsize < U > , U : PointeeSized > DispatchFromDyn < & 'a U > for & 'a T { }}}
mkitem!{mkimpl!{# [unstable (feature = "dispatch_from_dyn" , issue = "none")] impl < 'a , T : PointeeSized + Unsize < U > , U : PointeeSized > DispatchFromDyn < & 'a mut U > for & 'a mut T { }}}
mkitem!{mkimpl!{# [unstable (feature = "dispatch_from_dyn" , issue = "none")] impl < T : PointeeSized + Unsize < U > , U : PointeeSized > DispatchFromDyn < * const U > for * const T { }}}
mkitem!{mkimpl!{# [unstable (feature = "dispatch_from_dyn" , issue = "none")] impl < T : PointeeSized + Unsize < U > , U : PointeeSized > DispatchFromDyn < * mut U > for * mut T { }}}